        </div>
        <div>
          <dt>{StatusLabel.best}</dt> <dd>{best ?? 0}</dd>
        </div>
      </dl>
      {isWon(game) && (
        <p className={`victory${celebration ? ' celebrate' : ''}`}>
          Every pair found in {game.moves} moves and {formatElapsed(game.elapsedMs)}. Well played.
        </p>
      )}
    </>
  );
}
export const StatusLabel = {
  moves: 'Moves:',
  pairs: 'Pairs:',
  time: 'Time:',
  best: 'Best:',
} as const;
import { activateCard, advanceGame, createGame, isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { rememberBest } from './storage.ts';
import type { GameState } from '../game.ts';
import type { Preferences } from './storage.ts';

export interface Session {
  readonly game: GameState;
  readonly paused: boolean;
  readonly generation: number;
  readonly feedback: string;
  readonly loadNotice: string;
  readonly announcement: number;
  readonly celebration: boolean;
  readonly preferences: Preferences;
}

export const SessionNotice = {
  loaded: 'Loaded snapshot. Select Resume to continue.',
  loadedCompleted: 'Loaded completed snapshot.',
  invalidBoard: 'Invalid board code.',
  invalidSnapshot: 'Invalid snapshot.',
} as const;

export function initialSession(code: string, preferences: Preferences): Session {
  return {
    game: createGame(code),
    paused: false,
    generation: 0,
    feedback: '',
    loadNotice: '',
    announcement: 0,
    celebration: false,
    preferences,
  };
}

export function replaceGame(session: Session, game: GameState, imported: boolean): Session {
  const paused = imported && !isWon(game);
  const loadNotice = imported
    ? paused
      ? SessionNotice.loaded
      : SessionNotice.loadedCompleted
    : '';
  return {
    ...session,
    game,
    paused,
    generation: session.generation + 1,
    celebration: false,
    preferences: { ...session.preferences, size: game.size },
    // Only loads have a published status. A new deal clears the last turn result silently.
    announcement: imported ? session.announcement + 1 : session.announcement,
    feedback: loadNotice,
    loadNotice,
  };
}

export function tickSession(session: Session, generation: number, milliseconds: number): Session {
  if (session.generation !== generation || session.paused) return session;
  const game = advanceGame(session.game, milliseconds);
  return game === session.game ? session : { ...session, game };
}

export function activateSession(session: Session, index: number): Session {
  if (session.paused) return session;
  const game = activateCard(session.game, index);
  if (game === session.game) return session;
  if (game.selection.kind === SelectionKind.one) return { ...session, game };
  const won = isWon(game);
  const feedback = won
    ? `Pair found. All pairs found in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}.`
    : game.selection.kind === SelectionKind.mismatch
      ? 'No match. Cards close after a short pause.'
      : `Pair found. ${game.matched.length / 2} ${game.matched.length === 2 ? 'pair' : 'pairs'} matched.`;
  const preferences = won
    ? rememberBest(session.preferences, game.size, game.moves)
    : session.preferences;
  return {
    ...session,
    game,
    feedback,
    announcement: session.announcement + 1,
    preferences,
    celebration: won,
  };
}

import { expect } from './browser-test.ts';
import type { Locator } from '@playwright/test';

export async function expectFocusInside(card: Locator): Promise<void> {
  const bounds = await card.evaluate((element) => {
    const viewport = element.closest('.board-viewport');
    if (!viewport) throw new Error('Missing board scroll area.');
    const outer = viewport.getBoundingClientRect();
    const inner = element.getBoundingClientRect();
    const style = getComputedStyle(element);
    const ring = parseFloat(style.outlineWidth) + parseFloat(style.outlineOffset);
    return {
      left: inner.left - ring - outer.left - viewport.clientLeft,
      top: inner.top - ring - outer.top - viewport.clientTop,
      right: outer.left + viewport.clientLeft + viewport.clientWidth - inner.right - ring,
      bottom: outer.top + viewport.clientTop + viewport.clientHeight - inner.bottom - ring,
      windowLeft: inner.left - ring,
      windowTop: inner.top - ring,
      windowRight: innerWidth - inner.right - ring,
      windowBottom: innerHeight - inner.bottom - ring,
    };
  });
  for (const [edge, value] of Object.entries(bounds))
    expect(value, `V19 full focus outline ${edge}`).toBeGreaterThanOrEqual(-0.25);
}

// Distances from the card to each edge of the board's scroll area, with the card's scroll margin.
export async function boardGaps(card: Locator) {
  return card.evaluate((element) => {
    const viewport = element.closest('.board-viewport');
    if (!viewport) throw new Error('Missing board scroll area.');
    const outer = viewport.getBoundingClientRect();
    const inner = element.getBoundingClientRect();
    return {
      margin: parseFloat(getComputedStyle(element).scrollMarginRight),
      left: inner.left - outer.left - viewport.clientLeft,
      right: outer.left + viewport.clientLeft + viewport.clientWidth - inner.right,
      top: inner.top - outer.top - viewport.clientTop,
      bottom: outer.top + viewport.clientTop + viewport.clientHeight - inner.bottom,
    };
  });
}
import { expect, test } from './browser-test.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { loadFixedBoard } from './game-fixture.ts';
import { boardGaps } from './focus-bounds.ts';
import type { Locator, Page } from '@playwright/test';

const SIZE = 16;
const LAST = SIZE ** 2 - 1;
// Pressed 4px inside the board edge, so the card shows only a sliver there.
const EDGE_INSET_PX = 4;
const WHEEL_PX = 240;
const SUBPIXEL_PX = 0.25;
// The two stated viewports, and the zoomed one at 640x400 where a card can be clipped.
const VIEWS = [
  { width: 360, height: 800, scale: 1 },
  { width: 1280, height: 800, scale: 1 },
  { width: 640, height: 400, scale: 2 },
] as const;
const TOUCH_VIEWS = VIEWS;
// A busy machine can show one unchanged frame while a scroll still runs, so the wheel waits for several.
const SETTLED_FRAMES = 10;

// After the press completes, the focused card sits fully inside the board and the window, with
// nearest alignment leaving just the card's scroll margin at the edge it came in by.
async function expectSettledInView(card: Locator, message: string): Promise<void> {
  await expect(card).toBeFocused();
  const gaps = await boardGaps(card);
  // Scroll offsets are whole pixels, so fractional card sizes can leave up to 1px more.
  expect(gaps.bottom, message).toBeGreaterThanOrEqual(gaps.margin - SUBPIXEL_PX);
  expect(gaps.bottom, message).toBeLessThan(gaps.margin + 1);
  const box = await card.boundingBox();
  const view = card.page().viewportSize();
  if (!box || !view) throw new Error('Missing card or viewport.');
  expect(box.y + box.height, message).toBeLessThanOrEqual(view.height);
}

async function largeBoard(page: Page): Promise<Locator> {
  await loadFixedBoard(page);
  await page.getByLabel(DealControl.size, { exact: true }).selectOption(String(SIZE));
  const cards = page.locator('.card');
  await expect(cards).toHaveCount(SIZE ** 2);
  return cards;
}

async function restart(page: Page): Promise<void> {
  await page.getByRole('button', { name: DealControl.restart, exact: true }).click();
  await expect(page.locator('.card.revealed')).toHaveCount(0);
}

// A programmatic scroll that brings the board's bottom edge into the window.
function showBoardEnd(page: Page): Promise<void> {
  return page
    .locator('.board-viewport')
    .evaluate((viewport) => viewport.scrollIntoView({ block: 'end' }));
}

// The first visible card that the board's bottom edge cuts through, with room to press its sliver.
// When a row boundary sits on the edge, a programmatic board scroll of half a card moves one there.
function clippedPoint(page: Page) {
  return page.locator('.board-viewport').evaluate((viewport, inset) => {
    const outer = viewport.getBoundingClientRect();
    const bottom = outer.top + viewport.clientTop + viewport.clientHeight;
    const cards = [...viewport.querySelectorAll('.card')];
    const crossing = () =>
      cards.findIndex((card) => {
        const box = card.getBoundingClientRect();
        return box.top < bottom - 2 * inset && box.bottom > bottom && box.left >= outer.left;
      });
    let index = crossing();
    if (index < 0) {
      viewport.scrollTop += (cards[0]?.getBoundingClientRect().height ?? 0) / 2;
      index = crossing();
    }
    const box = cards[index]?.getBoundingClientRect();
    if (!box) throw new Error('No card crosses the board edge.');
    return { index, x: box.left + box.width / 2, y: bottom - inset };
  }, EDGE_INSET_PX);
}

// Waits until the wheel's scroll has landed, so the pressed card is the one under the pointer.
async function wheelBoard(page: Page): Promise<void> {
  const viewport = page.locator('.board-viewport');
  const before = await viewport.evaluate((element) => element.scrollTop);
  await page.mouse.wheel(0, WHEEL_PX);
  await expect.poll(() => viewport.evaluate((element) => element.scrollTop)).not.toBe(before);
  await viewport.evaluate(
    (element, frames) =>
      new Promise<void>((settled) => {
        let last = element.scrollTop;
        let stable = 0;
        const check = () => {
          stable = element.scrollTop === last ? stable + 1 : 0;
          last = element.scrollTop;
          if (stable >= frames) settled();
          else requestAnimationFrame(check);
        };
        requestAnimationFrame(check);
      }),
    SETTLED_FRAMES,
  );
}

for (const view of VIEWS)
  test(
    `pointer clicks reveal the pressed card on ${SIZE}x${SIZE} at ${view.width}x${view.height}`,
    async ({ page }) => {
      const cards = await largeBoard(page);
      await cards.nth(LAST).click();
      await expect(cards.nth(LAST), 'I01 click after scrolling into view').toHaveClass(/revealed/);
      await restart(page);
